INSERT INTO profiles (id, email, full_name, role, phone, avatar_url, bio, region) VALUES
('11111111-1111-1111-1111-111111111111', 'sunita.devi@kalavaibhav.demo', 'Sunita Devi', 'artisan', '+91 98450 12345', 'https://images.unsplash.com/photo-1544005313-94ddf0286df2?auto=format&fit=crop&w=400&q=80', 'Master artisan in GI-tagged Kasuti embroidery from Dharwad, Karnataka. Practicing traditional geometric needlework for over 18 years.', 'Dharwad, Karnataka'),
('22222222-2222-2222-2222-222222222222', 'rameshwar.soni@kalavaibhav.demo', 'Rameshwar Soni', 'artisan', '+91 98290 67890', 'https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?auto=format&fit=crop&w=400&q=80', 'Third-generation Blue Pottery ceramist from Kot Jeweler, Jaipur. Preserving quartz stone and natural cobalt oxide glazing techniques.', 'Jaipur, Rajasthan'),
('33333333-3333-3333-3333-333333333333', 'manju.gowda@kalavaibhav.demo', 'Manju Gowda', 'artisan', '+91 94480 34567', 'https://images.unsplash.com/photo-1500648767791-00dcc994a43e?auto=format&fit=crop&w=400&q=80', 'Dedicated turner and carver of Channapatna GI-certified lacquer toys using natural vegetable dyes and Hale wood.', 'Channapatna, Karnataka'),
('44444444-4444-4444-4444-444444444444', 'anamika.buyer@kalavaibhav.demo', 'Anamika Sharma', 'buyer', '+91 98110 55555', 'https://images.unsplash.com/photo-1534528741775-53994a69daeb?auto=format&fit=crop&w=400&q=80', 'Architect & folk art collector interested in authentic regional craft commissions and sustainable home decor.', 'Bengaluru, Karnataka'),
('55555555-5555-5555-5555-555555555555', 'curator.admin@kalavaibhav.demo', 'Vikramaditya Rao', 'admin', '+91 99000 99999', 'https://images.unsplash.com/photo-1472099645785-5658abf4ff4e?auto=format&fit=crop&w=400&q=80', 'Platform Curator & Provenance Verification Officer at Kala Vaibhav.', 'New Delhi');
