('aa111111-1111-1111-1111-111111111111', '11111111-1111-1111-1111-111111111111', 'Kasuti Embroidery', 18, 'Gokul Road, Dharwad', 'Karnataka', 'independently-verified', 'State Handicraft Board certified master trainer. Verified on-site workshop audit.', true, true),
('aa222222-2222-2222-2222-222222222222', '22222222-2222-2222-2222-222222222222', 'Jaipur Blue Pottery', 24, 'Kukas Artisan Cluster, Jaipur', 'Rajasthan', 'independently-verified', 'National awardee lineage; authentic quartz glazing audit completed.', true, true),
('aa333333-3333-3333-3333-333333333333', '33333333-3333-3333-3333-333333333333', 'Channapatna Lacquerware', 12, 'Craft Complex, Channapatna', 'Karnataka', 'community-reviewed', 'Member of Karnataka Channapatna Crafts Guild; verified non-toxic dye certificate.', true, true);
INSERT INTO products (id, artisan_id, title, craft_type, category, description, price, currency, materials, time_to_make, stock_quantity, status, region) VALUES
('p1010101-1010-1010-1010-101010101010', '11111111-1111-1111-1111-111111111111', 'Hand-Embroidered Kasuti Silk Tote Bag', 'Kasuti Embroidery', 'Textiles & Embroidery', 'A heritage tote bag crafted in pure mulberry raw silk featuring intricate Gavanti (double running stitch) and Muragi (zigzag) motifs of temple towers (Gopuram) and sacred peacocks. No knot is visible on either side.', 1450.00, 'INR', 'Pure Mulberry Silk, Hand-spun Cotton Thread', '5 days', 6, 'active', 'Karnataka'),
('p2020202-2020-2020-2020-202020202020', '22222222-2222-2222-2222-222222222222', 'Handcrafted Cobalt Blue Quartz Vase', 'Blue Pottery', 'Pottery & Ceramics', 'Traditional Jaipur Blue Pottery vase crafted from crushed quartz stone powder, Fuller''s earth, and natural gum, adorned with royal Mughal botanical motifs painted by squirrel-hair brush in cobalt and turquoise.', 2200.00, 'INR', 'Quartz Stone Powder, Glass, Katira Gum, Natural Cobalt Oxide', '7 days', 4, 'active', 'Rajasthan'),
('p3030303-3030-3030-3030-303030303030', '33333333-3333-3333-3333-333333333333', 'GI-Certified Channapatna Wooden Stacking Rings', 'Woodwork & Toys', 'Toys & Living', 'Safe, eco-friendly Montessori stacking toy hand-turned on traditional lathe from seasoned Wrightia tinctoria (Aale Mara) softwood. Lustrous finish achieved solely with natural tree lacquer and vegetable turmeric/indigo dyes.', 780.00, 'INR', 'Seasoned Hale Wood, Natural Lac Resin, Turmeric, Indigo', '2 days', 15, 'active', 'Karnataka'),
('p4040404-4040-4040-4040-404040404040', '11111111-1111-1111-1111-111111111111', 'Kasuti Temple Border Handloom Dupatta', 'Kasuti Embroidery', 'Textiles & Embroidery', 'Fine handwoven Chanderi cotton-silk dupatta adorned with traditional chariot (Ratha) and lotus (Kamala) Kasuti needlework on borders and pallu. Each geometric motif requires over 1,200 counted threads.', 3600.00, 'INR', 'Chanderi Cotton-Silk, Resham Threads', '12 days', 3, 'active', 'Karnataka');
