INSERT INTO craft_passports (id, product_id, passport_number, artisan_id, craft_name, region, materials, techniques, time_and_effort, cultural_story, provenance_status, verification_details) VALUES
('pass-1', 'p1010101-1010-1010-1010-101010101010', 'KV-PASSPORT-KTK-2026-0041', '11111111-1111-1111-1111-111111111111', 'Kasuti Needlecraft of Karnataka', 'Dharwad, Karnataka (GI Registry 2006)', 'Pure Raw Silk, Organic dyed cotton thread', 'Counted-thread embroidery with Gavanti, Muragi, Negi, and Menthi stitches without frame or tracings', '5 working days (approx 34 hours of fine hand-needlework)', 'Kasuti has been practiced since the Chalukya dynasty (6th-12th century). Women traditionally stitched cradle covers and wedding saris with symbols of divine protection and sacred architecture.', 'independently-verified', '{"verifiedBy": "Karnataka Handloom Development Board Audit", "auditDate": "2026-04-12", "giCertified": true}'::jsonb),
('pass-2', 'p2020202-2020-2020-2020-202020202020', 'KV-PASSPORT-RAJ-2026-0118', '22222222-2222-2222-2222-222222222222', 'Jaipur Blue Pottery Glazed Ware', 'Jaipur, Rajasthan (GI Registry 2008)', 'Ground quartz powder, cullet glass, katira gond, Multani mitti', 'Low-fire ceramic casting without clay, manual hand-painting with mineral oxides, and lead-free quartz glazing', '7 days including curing, drying, detailing and 800°C kiln firing', 'Brought to Jaipur under Sawai Ram Singh II in the 19th century, this unique pottery uses no clay and produces a characteristic translucent, semi-porcelain finish prized worldwide.', 'independently-verified', '{"verifiedBy": "Jaipur Handicrafts Association", "auditDate": "2026-05-19", "giCertified": true}'::jsonb),
('pass-3', 'p3030303-3030-3030-3030-303030303030', 'KV-PASSPORT-KTK-2026-0205', '33333333-3333-3333-3333-333333333333', 'Channapatna Ivory-Wood Lacquerware', 'Channapatna (Gombegala Ooru), Karnataka', 'Wrightia tinctoria softwood, natural button lac, vegetable turmeric, indigo', 'Hand lathe-turning, friction-burnishing with dry screw pine leaf (Talegari) for natural high gloss', '2 days handcrafting and seasoning', 'Originating during Tipu Sultan''s reign, who invited Persian artisans to train locals in lathe woodworking. Today it is celebrated globally as India''s safest, non-toxic eco-toy heritage.', 'community-reviewed', '{"reviewedBy": "Channapatna Artisans Welfare Cooperative", "communityConsensus": "Authentic Hale Wood and Non-toxic Lacquer"}'::jsonb);
INSERT INTO craft_journey_items (id, product_id, artisan_id, title, description, media_url, media_type, step_order, milestone_date) VALUES
('cj1-1', 'p1010101-1010-1010-1010-101010101010', '11111111-1111-1111-1111-111111111111', 'Selecting Handloom Silk Fabric', 'Carefully inspecting the warp and weft density of pure raw silk to ensure each warp thread can be accurately counted by eye.', 'https://images.unsplash.com/photo-1606760227091-3dd870d97f1d?auto=format&fit=crop&w=800&q=80', 'image', 1, '2026-09-01'),
('cj1-2', 'p1010101-1010-1010-1010-101010101010', '11111111-1111-1111-1111-111111111111', 'Executing Gavanti (Double-Running) Stitch', 'Executing the sacred temple chariot motif. No pencil marks are drawn; the pattern emerges through patient mathematical thread counting.', 'https://images.unsplash.com/photo-1590874103328-eac38a683ce7?auto=format&fit=crop&w=800&q=80', 'image', 2, '2026-09-03'),
('cj1-3', 'p1010101-1010-1010-1010-101010101010', '11111111-1111-1111-1111-111111111111', 'Lining and Finishing with Brass Hardware', 'Hand-stitching interior pocket compartments and reinforcing dual-density cotton strap handles with antique brass rivets.', 'https://images.unsplash.com/photo-1544816155-12df9643f363?auto=format&fit=crop&w=800&q=80', 'image', 3, '2026-09-05'),
('cj2-1', 'p2020202-2020-2020-2020-202020202020', '22222222-2222-2222-2222-222222222222', 'Preparing Quartz Stone Dough', 'Pulverizing pure white quartz pebbles from the Aravalli hills, mixing with Katira gum and water into a smooth clay-free dough.', 'https://images.unsplash.com/photo-1565193566173-7a0ee3dbe261?auto=format&fit=crop&w=800&q=80', 'image', 1, '2026-09-10'),
('cj2-2', 'p2020202-2020-2020-2020-202020202020', '22222222-2222-2222-2222-222222222222', 'Freehand Floral Painting with Cobalt Oxide', 'Painting traditional leafy creepers and lotuses using a fine camel hair brush loaded with natural cobalt oxide mineral pigment.', 'https://images.unsplash.com/photo-1578749556568-bc2c40e68b61?auto=format&fit=crop&w=800&q=80', 'image', 2, '2026-09-14'),
('cj2-3', 'p2020202-2020-2020-2020-202020202020', '22222222-2222-2222-2222-222222222222', 'Firing in Traditional Wood Kiln', 'Carefully stacking within the muffle kiln and firing at 800°C for 72 hours of gradual heat and slow cooling.', 'https://images.unsplash.com/photo-1612196808214-b8e1d6145a8c?auto=format&fit=crop&w=800&q=80', 'image', 3, '2026-09-17');
INSERT INTO custom_requests (id, buyer_id, title, description, craft_type, preferences, reference_image_url, is_private, budget_min, budget_max, desired_date, status) VALUES
('cr-100', '44444444-4444-4444-4444-444444444444', 'Custom Wedding Kasuti Wall Hanging with Family Tree', 'Looking for a bespoke 24x36 inch Kasuti wall panel on natural tussar silk incorporating our ancestral village temple tower and initials.', 'Kasuti Embroidery', '{"size": "24x36 inches", "baseFabric": "Raw Tussar Silk", "colors": ["Indigo", "Madder Red", "Mustard"]}'::jsonb, 'https://images.unsplash.com/photo-1610030469983-98e550d6193c?auto=format&fit=crop&w=800&q=80', false, 4500.00, 7000.00, '2026-12-15', 'proposal_received');
INSERT INTO commission_proposals (id, custom_request_id, artisan_id, proposed_price, estimated_days, message, status) VALUES
('prop-100', 'cr-100', '11111111-1111-1111-1111-111111111111', 5800.00, 18, 'Namaste Anamika ji. I would love to create this heritage heirloom for you. I have authentic hand-spun Tussar silk from Karnataka Sericulture. We will use traditional Muragi and Gavanti stitches for the family temple motif. I will provide work-in-progress photos every 5 days.', 'pending');
